1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { Prisma } from "@prisma/client";
4	import { db } from "@/lib/db";
5	import { getAdminUser } from "@/lib/auth";
6	import {
7	  Empty,
8	  StatTile,
9	  TableFrame,
10	  Th,
11	  formatDate,
12	  formatUsd,
13	  truncate,
14	} from "./ui";
15	
16	export const dynamic = "force-dynamic";
17	
18	const PAGE_SIZE = 25;
19	
20	type SortKey = "recent" | "oldest" | "email" | "projects";
21	
22	/**
23	 * Only DATABASE-NATIVE sorts are offered. Balance, lifetime spend and build
24	 * count are all derived from other tables and are computed per PAGE (see
25	 * below) — sorting the page by one of them would silently sort 25 arbitrary
26	 * rows rather than the whole table, which is worse than not offering it.
27	 */
28	const SORTS: Record<SortKey, { label: string; orderBy: Prisma.UserOrderByWithRelationInput }> = {
29	  recent: { label: "Newest", orderBy: { createdAt: "desc" } },
30	  oldest: { label: "Oldest", orderBy: { createdAt: "asc" } },
31	  email: { label: "Email", orderBy: { email: "asc" } },
32	  projects: { label: "Projects", orderBy: { projects: { _count: "desc" } } },
33	};
34	
35	function isSortKey(v: unknown): v is SortKey {
36	  return typeof v === "string" && v in SORTS;
37	}
38	
39	function first(v: string | string[] | undefined): string {
40	  if (Array.isArray(v)) return v[0] ?? "";
41	  return v ?? "";
42	}
43	
44	function href(params: { q: string; sort: SortKey; page: number }): string {
45	  const sp = new URLSearchParams();
46	  if (params.q) sp.set("q", params.q);
47	  if (params.sort !== "recent") sp.set("sort", params.sort);
48	  if (params.page > 1) sp.set("page", String(params.page));
49	  const qs = sp.toString();
50	  return qs ? `/admin/users?${qs}` : "/admin/users";
51	}
52	
53	// ── Per-page rollups ──────────────────────────────────────────────────────
54	// Everything below is keyed by userId and fetched for the CURRENT PAGE ONLY,
55	// in a fixed number of queries (6) regardless of how many users are on it.
56	// No query ever runs inside a loop over users.
57	
58	type BalanceRow = { userId: string; balanceAfter: number };
59	
60	type BuildRollupRow = {
61	  userId: string;
62	  builds: number;
63	  succeeded: number;
64	  failed: number;
65	  costMicros: bigint;
66	  creditsCharged: bigint;
67	  lastBuildAt: Date | null;
68	};
69	
70	type Rollup = {
71	  balance: number;
72	  netDelta: number;
73	  spent: number;
74	  builds: number;
75	  succeeded: number;
76	  failed: number;
77	  costMicros: number;
78	  creditsCharged: number;
79	  lastBuildAt: Date | null;
80	};
81	
82	const EMPTY_ROLLUP: Rollup = {
83	  balance: 0,
84	  netDelta: 0,
85	  spent: 0,
86	  builds: 0,
87	  succeeded: 0,
88	  failed: 0,
89	  costMicros: 0,
90	  creditsCharged: 0,
91	  lastBuildAt: null,
92	};
93	
94	export default async function AdminUsersPage({
95	  searchParams,
96	}: {
97	  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
98	}) {
99	  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
100	  // is not an authorization boundary on its own (it does not re-render on
101	  // every navigation within the section). Same idiom as app/admin/page.tsx:
102	  // 404 rather than redirect, so a non-admin learns nothing about this path.
103	  if (!(await getAdminUser())) notFound();
104	
105	  const sp = await searchParams;
106	  const q = first(sp.q).trim();
107	  const sortRaw = first(sp.sort);
108	  const sort: SortKey = isSortKey(sortRaw) ? sortRaw : "recent";
109	  const pageRaw = Number.parseInt(first(sp.page), 10);
110	  const page = Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1;
111	
112	  // Search by email, by display name, or by pasting a raw user id straight out
113	  // of a log line or a support ticket.
114	  const where: Prisma.UserWhereInput = q
115	    ? {
116	        OR: [
117	          { email: { contains: q, mode: "insensitive" } },
118	          { name: { contains: q, mode: "insensitive" } },
119	          { id: q },
120	        ],
121	      }
122	    : {};
123	
124	  const [total, users] = await Promise.all([
125	    db.user.count({ where }),
126	    db.user.findMany({
127	      where,
128	      // `id` breaks ties so pagination is stable when timestamps collide.
129	      orderBy: [SORTS[sort].orderBy, { id: "asc" }],
130	      skip: (page - 1) * PAGE_SIZE,
131	      take: PAGE_SIZE,
132	      select: {
133	        id: true,
134	        email: true,
135	        name: true,
136	        role: true,
137	        createdAt: true,
138	        spendCapCredits: true,
139	        _count: { select: { projects: true } },
140	      },
141	    }),
142	  ]);
143	
144	  const ids = users.map((u) => u.id);
145	
146	  // ── Balance for many users, without one query each ────────────────────
147	  // lib/credits.ts `getBalance` reads `balanceAfter` off the user's NEWEST
148	  // ledger row. Postgres does that for a whole set of users in one pass with
149	  // DISTINCT ON: sort by (userId, createdAt DESC, id DESC) and keep the first
150	  // row per userId. `id` is the tiebreak so two rows written inside the same
151	  // millisecond still resolve deterministically to the same row Prisma's
152	  // findFirst would have picked.
153	  const balanceRows = ids.length
154	    ? await db.$queryRaw<BalanceRow[]>`
155	        SELECT DISTINCT ON (l."userId") l."userId", l."balanceAfter"
156	        FROM "CreditLedger" l
157	        WHERE l."userId" IN (${Prisma.join(ids)})
158	        ORDER BY l."userId", l."createdAt" DESC, l."id" DESC`
159	    : [];
160	
161	  // Build has no userId — it hangs off Project — so the per-user build
162	  // rollup is one grouped join rather than a per-user count.
163	  const buildRows = ids.length
164	    ? await db.$queryRaw<BuildRollupRow[]>`
165	        SELECT p."userId",
166	               COUNT(*)::int AS "builds",
167	               COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
168	               COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
169	               COALESCE(SUM(b."costMicros"), 0)::bigint AS "costMicros",
170	               COALESCE(SUM(b."creditsCharged"), 0)::bigint AS "creditsCharged",
171	               MAX(b."createdAt") AS "lastBuildAt"
172	        FROM "Build" b
173	        JOIN "Project" p ON p."id" = b."projectId"
174	        WHERE p."userId" IN (${Prisma.join(ids)})
175	        GROUP BY p."userId"`
176	    : [];
177	
178	  const [spentRows, netRows] = ids.length
179	    ? await Promise.all([
180	        db.creditLedger.groupBy({
181	          by: ["userId"],
182	          where: { userId: { in: ids }, delta: { lt: 0 } },
183	          _sum: { delta: true },
184	        }),
185	        // The ledger is append-only and starts at zero, so the sum of every
186	        // delta MUST equal the newest row's balanceAfter. Cheap to check here
187	        // (one grouped query for the page) and the only way to notice a
188	        // ledger that has drifted before a customer does.
189	        db.creditLedger.groupBy({
190	          by: ["userId"],
191	          where: { userId: { in: ids } },
192	          _sum: { delta: true },
193	        }),
194	      ])
195	    : [[], []];
196	
197	  const rollups = new Map<string, Rollup>(ids.map((id) => [id, { ...EMPTY_ROLLUP }]));
198	  for (const r of balanceRows) {
199	    const u = rollups.get(r.userId);
200	    if (u) u.balance = r.balanceAfter;
201	  }
202	  for (const r of buildRows) {
203	    const u = rollups.get(r.userId);
204	    if (!u) continue;
205	    u.builds = Number(r.builds);
206	    u.succeeded = Number(r.succeeded);
207	    u.failed = Number(r.failed);
208	    u.costMicros = Number(r.costMicros);
209	    u.creditsCharged = Number(r.creditsCharged);
210	    u.lastBuildAt = r.lastBuildAt;
211	  }
212	  for (const r of spentRows) {
213	    const u = rollups.get(r.userId);
214	    // Deltas are negative for spend; show it as a positive number.
215	    if (u) u.spent = Math.abs(r._sum.delta ?? 0);
216	  }
217	  for (const r of netRows) {
218	    const u = rollups.get(r.userId);
219	    if (u) u.netDelta = r._sum.delta ?? 0;
220	  }
221	
222	  const pageCount = Math.max(1, Math.ceil(total / PAGE_SIZE));
223	  const drifted = [...rollups.values()].filter((r) => r.balance !== r.netDelta).length;
224	
225	  return (
226	    <div className="mx-auto max-w-6xl px-6 py-10">
227	      <div className="mb-8">
228	        <Link
229	          href="/admin"
230	          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
231	        >
232	          ← kodely admin
233	        </Link>
234	        <div className="mt-1 text-lg font-semibold tracking-tight">Users</div>
235	        <p className="text-sm text-black/60 dark:text-white/60">
236	          Read-only. Per-customer credits, builds and cost — the view that answers a billing
237	          email.
238	        </p>
239	      </div>
240	
241	      <div className="mb-6 grid grid-cols-2 gap-4 sm:grid-cols-4">
242	        <StatTile label="Users matching" value={total} />
243	        <StatTile label="On this page" value={users.length} />
244	        <StatTile label="Page" value={`${page} / ${pageCount}`} />
245	        <StatTile
246	          label="Ledger drift"
247	          value={drifted}
248	          tone={drifted > 0 ? "warn" : undefined}
249	          hint="balanceAfter vs sum of deltas, this page"
250	        />
251	      </div>
252	
253	      <form method="get" action="/admin/users" className="mb-6 flex flex-wrap items-center gap-2">
254	        <input
255	          type="search"
256	          name="q"
257	          defaultValue={q}
258	          placeholder="Search email, name or user id"
259	          aria-label="Search users"
260	          className="w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30"
261	        />
262	        <select
263	          name="sort"
264	          defaultValue={sort}
265	          aria-label="Sort users"
266	          className="rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none dark:border-white/10"
267	        >
268	          {(Object.keys(SORTS) as SortKey[]).map((k) => (
269	            <option key={k} value={k}>
270	              {SORTS[k].label}
271	            </option>
272	          ))}
273	        </select>
274	        <button
275	          type="submit"
276	          className="rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
277	        >
278	          Search
279	        </button>
280	        {q ? (
281	          <Link
282	            href="/admin/users"
283	            className="text-sm text-black/50 underline-offset-4 hover:underline dark:text-white/50"
284	          >
285	            Clear
286	          </Link>
287	        ) : null}
288	      </form>
289	
290	      {users.length === 0 ? (
291	        <Empty>{q ? `No users match “${truncate(q, 40)}”.` : "No users yet."}</Empty>
292	      ) : (
293	        <TableFrame>
294	          <thead>
295	            <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
296	              <Th>Email</Th>
297	              <Th>Signed up</Th>
298	              <Th>Role</Th>
299	              <Th align="right">Projects</Th>
300	              <Th align="right">Builds</Th>
301	              <Th align="right">Balance</Th>
302	              <Th align="right">Spent</Th>
303	              <Th align="right">Cost</Th>
304	            </tr>
305	          </thead>
306	          <tbody className="divide-y divide-black/10 dark:divide-white/10">
307	            {users.map((u) => {
308	              const r = rollups.get(u.id) ?? EMPTY_ROLLUP;
309	              const drift = r.balance !== r.netDelta;
310	              return (
311	                <tr key={u.id}>
312	                  <td className="max-w-xs px-4 py-2">
313	                    <Link
314	                      href={`/admin/users/${u.id}`}
315	                      className="font-medium underline-offset-4 hover:underline"
316	                    >
317	                      {truncate(u.email, 44)}
318	                    </Link>
319	                    {u.name ? (
320	                      <div className="text-xs text-black/50 dark:text-white/50">
321	                        {truncate(u.name, 44)}
322	                      </div>
323	                    ) : null}
324	                  </td>
325	                  <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
326	                    {formatDate(u.createdAt)}
327	                  </td>
328	                  <td className="px-4 py-2 text-black/70 dark:text-white/70">
329	                    {u.role === "ADMIN" ? (
330	                      <span className="font-medium">ADMIN</span>
331	                    ) : (
332	                      <span className="text-black/50 dark:text-white/50">{u.role}</span>
333	                    )}
334	                  </td>
335	                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
336	                    {u._count.projects}
337	                  </td>
338	                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
339	                    {r.builds}
340	                    {r.builds > 0 ? (
341	                      <span className="ml-2 text-xs">
342	                        <span className="text-emerald-600 dark:text-emerald-400">{r.succeeded}</span>
343	                        <span className="text-black/30 dark:text-white/30"> / </span>
344	                        <span className="text-red-600 dark:text-red-400">{r.failed}</span>
345	                      </span>
346	                    ) : null}
347	                  </td>
348	                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums">
349	                    <span className={r.balance === 0 ? "text-red-600 dark:text-red-400" : ""}>
350	                      {r.balance}
351	                    </span>
352	                    {drift ? (
353	                      <span
354	                        className="ml-1 text-amber-600 dark:text-amber-500"
355	                        title={`Ledger drift: newest balanceAfter is ${r.balance} but deltas sum to ${r.netDelta}`}
356	                      >
357	                        !
358	                      </span>
359	                    ) : null}
360	                    {u.spendCapCredits !== null ? (
361	                      <div className="text-xs text-black/50 dark:text-white/50">
362	                        cap {u.spendCapCredits}
363	                      </div>
364	                    ) : null}
365	                  </td>
366	                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
367	                    {r.spent}
368	                  </td>
369	                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
370	                    {formatUsd(r.costMicros, 4)}
371	                  </td>
372	                </tr>
373	              );
374	            })}
375	          </tbody>
376	        </TableFrame>
377	      )}
378	
379	      <div className="mt-4 flex items-center justify-between text-sm">
380	        <span className="text-black/50 dark:text-white/50">
381	          {total === 0
382	            ? "0 users"
383	            : `${(page - 1) * PAGE_SIZE + 1}–${Math.min(page * PAGE_SIZE, total)} of ${total}`}
384	        </span>
385	        <span className="flex gap-2">
386	          {page > 1 ? (
387	            <Link
388	              href={href({ q, sort, page: page - 1 })}
389	              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
390	            >
391	              Previous
392	            </Link>
393	          ) : null}
394	          {page < pageCount ? (
395	            <Link
396	              href={href({ q, sort, page: page + 1 })}
397	              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
398	            >
399	              Next
400	            </Link>
401	          ) : null}
402	        </span>
403	      </div>
404	
405	      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
406	        Balance is the newest ledger row&apos;s balanceAfter, matching lib/credits.ts. Spent is the
407	        sum of negative deltas. Cost is real model spend across every build on the user&apos;s
408	        projects, charged or not — failed builds cost us money and are never billed.
409	      </p>
410	    </div>
411	  );
412	}
