// Failure clustering for Build.error.
//
// Build.error is a free-text string written by three different layers (the
// generate route, lib/build-site.ts, and whatever the SDK or the Anthropic
// client threw), truncated to 1000 chars. Listing those raw answers nothing:
// "is generation broken right now" is a question about FAMILIES, not strings.
// Six rows reading "Not logged in · Please run /login" are one incident, and
// the panel has to say so.
//
// The families below were derived from the error text actually present in this
// database plus every string the code can produce:
//
//   - "Claude Code returned an error result: Not logged in · Please run /login"
//   - "Claude Code returned an error result: Failed to authenticate.
//      API Error: 401 OAuth access token is invalid."
//   - "Error: EPERM: operation not permitted, symlink
//      'C:\home\kodely\kodely-foundation\node_modules' -> '...\kodely-build-*'"
//   - "EBUSY: resource busy or locked, rmdir '...\kodely-personal-*'"
//   - "Build timed out."                       (lib/build-site.ts, 60s vite bound)
//   - "Build failed:\n<vite stderr>"           (lib/build-site.ts)
//   - "Build could not start: <spawn error>"   (lib/build-site.ts)
//   - "Generation ended without producing output." (app/api/generate/route.ts)
//   - "Client disconnected."                       (app/api/generate/route.ts)
//   - "KODELY_ENGINE=sdk but no subscription credentials were found. …"
//     (lib/agent-sdk.ts)
//
// Adding a family is a deliberate edit, the same discipline as EVENTS in
// lib/events.ts. A growing "Other" share is the signal that these rules have
// drifted from what the system actually emits — which is why Other is shown
// with its own callout rather than quietly absorbing everything.

/**
 * Who has to act. This is the difference between "the box is broken" and "the
 * model is bad", and it is the single most useful thing the clustering adds:
 * a config family on top means no amount of prompt work will help.
 */
export type Blame = "config" | "environment" | "generation" | "client" | "unknown";

export type FamilyId =
  | "sdk_auth"
  | "api_auth"
  | "rate_limit"
  | "timeout"
  | "filesystem"
  | "foundation"
  | "compile"
  | "no_output"
  | "client_gone"
  | "other";

export type ErrorFamily = {
  id: FamilyId;
  label: string;
  blame: Blame;
  /** What to check. Names env VARS and files — never a value, never a secret. */
  hint: string;
  /** `null` for the catch-all, which is matched by exhaustion rather than by pattern. */
  test: RegExp | null;
};

/**
 * PRECEDENCE ORDER — first match wins, so the specific patterns come before
 * the broad ones. In particular `sdk_auth` is tested before `api_auth`,
 * because an OAuth 401 from the subscription engine also contains "401" and
 * would otherwise be filed as a metered-key problem, sending the operator to
 * the wrong env var.
 */
export const FAMILIES: ErrorFamily[] = [
  {
    id: "sdk_auth",
    label: "SDK subscription auth",
    blame: "config",
    hint: "The Claude Agent SDK engine is not logged in on the machine that runs generations. Run `claude setup-token` as that user, or set CLAUDE_CODE_OAUTH_TOKEN. Mirrors assertSdkCredentials() in lib/agent-sdk.ts. Nothing reaches the model, so these fail in seconds and cost nothing.",
    test: /not logged in|please run \/login|oauth access token|failed to authenticate|setup-token|CLAUDE_CODE_OAUTH_TOKEN|no subscription credentials/i,
  },
  {
    id: "api_auth",
    label: "Anthropic API key rejected",
    blame: "config",
    hint: "The metered key is missing, revoked or wrong. Check ANTHROPIC_API_KEY on the app host.",
    test: /authentication_error|invalid x-api-key|ANTHROPIC_API_KEY|permission_error|\b401\b|\b403\b/i,
  },
  {
    id: "rate_limit",
    label: "Rate limited / overloaded",
    blame: "environment",
    hint: "Upstream capacity, not our code. Transient — but a sustained share here means concurrency needs a ceiling.",
    test: /\b429\b|\b529\b|rate.?limit|overloaded_error|too many requests/i,
  },
  {
    id: "timeout",
    label: "Timed out",
    blame: "environment",
    hint: "lib/build-site.ts bounds the vite step at 60s and kills it with SIGTERM. A cluster here means the compile step, not the model, is the bottleneck.",
    test: /build timed out|\bSIGTERM\b|\bETIMEDOUT\b|timed? ?out/i,
  },
  {
    id: "filesystem",
    label: "Filesystem / sandbox",
    blame: "environment",
    hint: "The build sandbox could not be created or torn down — EPERM on symlink is the Windows privilege case lib/build-site.ts works around with a junction; EBUSY on rmdir is a file still held open. Host-specific, and never the user's fault.",
    test: /\bEPERM\b|\bEBUSY\b|\bEACCES\b|\bENOTEMPTY\b|\bEXDEV\b|\bEMFILE\b|\bENOSPC\b|operation not permitted|resource busy or locked/i,
  },
  {
    id: "foundation",
    label: "Foundation tree missing",
    blame: "config",
    hint: "The shared pre-installed node_modules could not be found, so vite had nothing to run against. Check KODELY_FOUNDATION_DIR and re-run scripts/install-foundation.mjs. This surfaces as a misleading \u201cCannot find module\u201d and has bitten twice.",
    test: /cannot find module|MODULE_NOT_FOUND|build could not start|\bENOENT\b[^\n]*node_modules|no such file or directory[^\n]*node_modules/i,
  },
  {
    id: "compile",
    label: "Generated code did not compile",
    blame: "generation",
    hint: "The model wrote a site vite could not build. This is the only family a better prompt or model actually fixes — and the one a repair pass is for.",
    test: /build failed:|\bvite\b|esbuild|rollup|transform failed|error TS\d+|could not resolve|failed to resolve import|unexpected token|parse error|is not exported by/i,
  },
  {
    id: "no_output",
    label: "Agent produced no files",
    blame: "generation",
    hint: "The run finished without writing anything — historically caused by the prompt naming a tool the engine does not expose (see the SDK tool-contract note in lib/agent-sdk.ts).",
    test: /generation ended without producing output|produced no (files|output)/i,
  },
  {
    id: "client_gone",
    label: "Client disconnected",
    blame: "client",
    hint: "The browser went away mid-stream. Not a defect — but a rising share can mean the build is slow enough that people give up.",
    test: /client disconnected/i,
  },
  {
    id: "other",
    label: "Other / unclassified",
    blame: "unknown",
    hint: "No rule matched. A rising share here means these families have drifted from what the system now emits — read the samples and add a rule in app/admin/health/errors.ts.",
    test: null,
  },
];

const BY_ID = new Map<FamilyId, ErrorFamily>(FAMILIES.map((f) => [f.id, f]));

export function family(id: FamilyId): ErrorFamily {
  // Non-null by construction: FamilyId is exactly the set of ids in FAMILIES.
  return BY_ID.get(id) ?? FAMILIES[FAMILIES.length - 1];
}

/** First matching family wins. A null/blank error is still a failure — file it as Other. */
export function classifyError(raw: string | null | undefined): FamilyId {
  const text = (raw ?? "").trim();
  if (!text) return "other";
  for (const f of FAMILIES) {
    if (f.test && f.test.test(text)) return f.id;
  }
  return "other";
}

export const BLAME_LABEL: Record<Blame, string> = {
  config: "our config",
  environment: "the host",
  generation: "the model",
  client: "the visitor",
  unknown: "unknown",
};

import { access } from "node:fs/promises";
import path from "node:path";
import { db } from "@/lib/db";
import { ENGINE } from "@/lib/agent";
import { isMailConfigured } from "@/lib/mail";
import { billingEnabled } from "@/lib/stripe";

// Dependency checks for /admin/health.
//
// SECRETS RULE, enforced by construction: every field below is a boolean, a
// duration, or a hand-written sentence. The only place an environment
// variable appears is in `env`, which holds NAMES. Nothing here ever reads a
// value into a string that reaches the page — not truncated, not masked. A
// masked secret is still a secret leak with extra steps, and an admin panel
// that prints "sk-ant-…f3a2" has put a fingerprint of the key in every
// screenshot of it.
//
// app/api/health/route.ts stays the LIVENESS probe: it answers "is the
// process up" with no dependencies, which is what a load balancer needs and
// what makes it safe to be unauthenticated. This module is the readiness
// view — it deliberately touches the things that probe must not.

export type CheckStatus = "ok" | "fail" | "warn" | "unknown";

export type Check = {
  id: string;
  label: string;
  status: CheckStatus;
  /** Names and booleans only — never a secret value. */
  detail: string;
  /** Environment variable NAMES this check reads. Values are never rendered. */
  env: string[];
};

/**
 * Mirrors lib/build-site.ts, which does not export it. If that default ever
 * changes, this line has to change with it — and the mismatch would show up
 * here as a check that disagrees with reality, which is the failure mode this
 * page exists to make visible.
 */
const FOUNDATION_DIR = process.env.KODELY_FOUNDATION_DIR ?? "/home/kodely/kodely-foundation";
const FOUNDATION_DIR_SET = Boolean(process.env.KODELY_FOUNDATION_DIR);

async function exists(p: string): Promise<boolean> {
  try {
    await access(p);
    return true;
  } catch {
    return false;
  }
}

export type DatabaseCheck = Check & { latencyMs: number | null };

/**
 * The one check that has to work when nothing else does. Every other panel on
 * the page is a query against this connection, so the page runs this first
 * and degrades to checks-only if it fails, rather than throwing a 500 at the
 * exact moment an operator is trying to find out what is wrong.
 */
export async function checkDatabase(): Promise<DatabaseCheck> {
  const started = Date.now();
  try {
    await db.$queryRaw`SELECT 1`;
    const latencyMs = Date.now() - started;
    return {
      id: "database",
      label: "Database reachable",
      status: latencyMs > 1000 ? "warn" : "ok",
      detail:
        latencyMs > 1000
          ? `SELECT 1 answered in ${latencyMs}ms — slow enough to be worth looking at.`
          : `SELECT 1 answered in ${latencyMs}ms.`,
      env: ["DATABASE_URL"],
      latencyMs,
    };
  } catch {
    return {
      id: "database",
      label: "Database reachable",
      status: "fail",
      // The driver's message can carry the connection string, so it is
      // deliberately swallowed rather than surfaced.
      detail:
        "SELECT 1 failed. The error is withheld here because a Postgres connection error can echo the DSN — read it from the server log.",
      env: ["DATABASE_URL"],
      latencyMs: null,
    };
  }
}

/**
 * The foundation tree is the shared, pre-installed node_modules every build
 * symlinks against instead of running `npm install` per generation. When it is
 * absent, vite fails with "Cannot find module", which reads like a bug in the
 * generated site and is not — this has cost debugging time twice.
 *
 * Three separate checks rather than one, because "the directory is there" is
 * not the question: the question is whether the exact entrypoint
 * lib/build-site.ts spawns is on disk.
 */
export async function checkFoundation(): Promise<Check[]> {
  const dirOk = await exists(FOUNDATION_DIR);
  const modulesOk = dirOk && (await exists(path.join(FOUNDATION_DIR, "node_modules")));
  const viteOk =
    modulesOk &&
    (await exists(path.join(FOUNDATION_DIR, "node_modules", "vite", "bin", "vite.js")));

  return [
    {
      id: "foundation-dir",
      label: "Foundation directory",
      status: dirOk ? "ok" : "fail",
      detail: dirOk
        ? FOUNDATION_DIR_SET
          ? "Present. KODELY_FOUNDATION_DIR is set and the path it names exists."
          : "Present, but KODELY_FOUNDATION_DIR is unset — this is the built-in Linux default path, which is wrong on a Windows host."
        : FOUNDATION_DIR_SET
          ? "Missing. KODELY_FOUNDATION_DIR is set but names a path that does not exist."
          : "Missing, and KODELY_FOUNDATION_DIR is unset, so lib/build-site.ts fell back to its Linux default path. On Windows that resolves under the drive root and every build fails at the symlink step.",
      env: ["KODELY_FOUNDATION_DIR"],
    },
    {
      id: "foundation-modules",
      label: "Foundation node_modules",
      status: modulesOk ? "ok" : "fail",
      detail: modulesOk
        ? "Present. Builds symlink this tree instead of installing per generation."
        : "Missing. Every build will fail with a misleading “Cannot find module”. Re-run scripts/install-foundation.mjs on this host.",
      env: ["KODELY_FOUNDATION_DIR"],
    },
    {
      id: "foundation-vite",
      label: "Vite entrypoint",
      status: viteOk ? "ok" : "fail",
      detail: viteOk
        ? "node_modules/vite/bin/vite.js is on disk — the exact file lib/build-site.ts spawns."
        : "node_modules/vite/bin/vite.js is absent. A node_modules directory that exists but is incomplete fails the same way as no directory at all.",
      env: [],
    },
  ];
}

export type EngineCheck = {
  engine: "api" | "sdk";
  /** True when recorded costMicros are imputed from a rate card rather than billed. */
  costsImputed: boolean;
  credentials: Check;
};

/**
 * Which generation engine is live, and whether it can authenticate.
 *
 * The credential check re-derives assertSdkCredentials() from lib/agent-sdk.ts
 * (which is private to that module) rather than importing it: importing
 * lib/agent-sdk.ts for its side effects would delete ANTHROPIC_API_KEY from
 * this process, which is a mutation an admin page has no business performing.
 */
export async function checkEngine(): Promise<EngineCheck> {
  if (ENGINE === "sdk") {
    const home = process.env.HOME ?? process.env.USERPROFILE;
    const hasToken = Boolean(process.env.CLAUDE_CODE_OAUTH_TOKEN);
    const hasCredentialsFile =
      Boolean(home) && (await exists(path.join(home as string, ".claude", ".credentials.json")));
    const ok = hasToken || hasCredentialsFile;

    return {
      engine: "sdk",
      costsImputed: true,
      credentials: {
        id: "engine-credentials",
        label: "SDK subscription credentials",
        status: ok ? "ok" : "fail",
        detail: ok
          ? hasToken
            ? "CLAUDE_CODE_OAUTH_TOKEN is set."
            : "A ~/.claude/.credentials.json written by `claude setup-token` is present for the user running this process."
          : "Neither CLAUDE_CODE_OAUTH_TOKEN nor ~/.claude/.credentials.json is present, so every generation will fail with “Not logged in” before reaching the model. There is deliberately no fallback to the metered API engine.",
        env: ["CLAUDE_CODE_OAUTH_TOKEN"],
      },
    };
  }

  const hasKey = Boolean(process.env.ANTHROPIC_API_KEY);
  return {
    engine: "api",
    costsImputed: false,
    credentials: {
      id: "engine-credentials",
      label: "Anthropic API key",
      status: hasKey ? "ok" : "fail",
      detail: hasKey
        ? "ANTHROPIC_API_KEY is set. Presence only — nothing here validates it against the API."
        : "ANTHROPIC_API_KEY is unset. The metered engine cannot start a generation.",
      env: ["ANTHROPIC_API_KEY"],
    },
  };
}

/** SMTP and Stripe both follow the "inert until configured" shape, so absent is a state, not an error. */
export function checkIntegrations(): Check[] {
  const mail = isMailConfigured();
  const stripe = billingEnabled();

  return [
    {
      id: "smtp",
      label: "SMTP configured",
      status: mail ? "ok" : "warn",
      detail: mail
        ? "Host, user and password are all set. Presence only — no connection is attempted from this page."
        : "Not configured. lib/mail.ts stays inert and callers return a clean 503, so transactional mail (welcome, low credits, build failed) silently does not send.",
      env: ["SMTP_HOST", "SMTP_PORT", "SMTP_USER", "SMTP_PASS", "MAIL_FROM"],
    },
    {
      id: "stripe",
      label: "Stripe configured",
      status: stripe ? "ok" : "warn",
      detail: stripe
        ? "Secret key and webhook secret are both set. Presence only — no call is made to Stripe."
        : "Not configured. Billing degrades gracefully and nobody can top up credits.",
      env: ["STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET"],
    },
  ];
}

import type { ReactNode } from "react";
import type { CheckStatus } from "./checks";

// Presentational helpers for /admin/health. Not a route — only page/layout/
// route filenames are routable — so this file is safe inside the segment.
//
// The vocabulary is the one app/admin/page.tsx and app/admin/users/ui.tsx
// already established: rounded-xl hairline borders, text-sm, tabular-nums on
// every figure, monochrome except where colour carries status meaning. Kept
// local rather than imported across admin subtrees so this page has no
// coupling to another section's internals.

export function truncate(text: string, max = 60): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

/**
 * Error text is multi-line and can contain fragments of a customer's source
 * code. Collapse it to a single line before it is ever rendered, then cut it
 * short — a list view is for recognising a shape, not for reading a log.
 */
export function oneLine(text: string, max = 150): string {
  return truncate(text.replace(/\s+/g, " ").trim(), max);
}

export function formatDuration(ms: number | null): string {
  if (ms === null || !Number.isFinite(ms)) return "—";
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m}m ${String(s).padStart(2, "0")}s`;
}

export function formatUsd(micros: number, decimals = 2): string {
  return `$${(micros / 1_000_000).toFixed(decimals)}`;
}

export function pct(n: number, d: number): number | null {
  if (d <= 0) return null;
  return Math.round((n / d) * 1000) / 10;
}

export function formatPct(v: number | null): string {
  return v === null ? "—" : `${v.toFixed(1)}%`;
}

export function Panel({
  title,
  subtitle,
  children,
  footnote,
}: {
  title: string;
  subtitle?: ReactNode;
  children: ReactNode;
  footnote?: ReactNode;
}) {
  return (
    <section className="rounded-xl border border-black/10 p-5 dark:border-white/10">
      <h2 className="text-sm font-medium">{title}</h2>
      {subtitle ? (
        <p className="mt-0.5 text-xs text-black/50 dark:text-white/50">{subtitle}</p>
      ) : null}
      <div className="mt-4">{children}</div>
      {footnote ? (
        <p className="mt-4 text-xs text-black/50 dark:text-white/50">{footnote}</p>
      ) : null}
    </section>
  );
}

export function StatTile({
  label,
  value,
  hint,
  tone,
}: {
  label: string;
  value: ReactNode;
  hint?: ReactNode;
  tone?: "warn" | "bad" | "good";
}) {
  const toneClass =
    tone === "bad"
      ? "text-red-600 dark:text-red-400"
      : tone === "warn"
        ? "text-amber-600 dark:text-amber-500"
        : tone === "good"
          ? "text-emerald-600 dark:text-emerald-400"
          : "";
  return (
    <div className="rounded-xl border border-black/10 p-4 dark:border-white/10">
      <div className="text-xs text-black/50 dark:text-white/50">{label}</div>
      <div className={`mt-1 text-xl font-semibold tabular-nums ${toneClass}`}>{value}</div>
      {hint ? <div className="mt-1 text-xs text-black/50 dark:text-white/50">{hint}</div> : null}
    </div>
  );
}

export function Empty({ children }: { children: ReactNode }) {
  return (
    <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
      {children}
    </div>
  );
}

/** Same dashed treatment as Empty, sized to sit inside a Panel. */
export function PanelEmpty({ children }: { children: ReactNode }) {
  return (
    <p className="rounded-lg border border-dashed border-black/15 p-6 text-center text-sm text-black/50 dark:border-white/15 dark:text-white/50">
      {children}
    </p>
  );
}

export function TableFrame({ children }: { children: ReactNode }) {
  return (
    <div className="overflow-x-auto rounded-xl border border-black/10 dark:border-white/10">
      <table className="w-full text-left text-sm">{children}</table>
    </div>
  );
}

export function Th({
  children,
  align = "left",
}: {
  children: ReactNode;
  align?: "left" | "right";
}) {
  return (
    <th className={`px-4 py-2 font-medium ${align === "right" ? "text-right" : ""}`}>{children}</th>
  );
}

const STATUS_DOT: Record<CheckStatus, string> = {
  ok: "bg-emerald-500",
  fail: "bg-red-500",
  warn: "bg-amber-500",
  unknown: "bg-black/25 dark:bg-white/25",
};

const STATUS_WORD: Record<CheckStatus, string> = {
  ok: "OK",
  fail: "FAIL",
  warn: "NOT SET",
  unknown: "UNKNOWN",
